before.code:
function slide(start) {
  requestAnimationFrame((now) => {
    const p = Math.min(1, (now - start) / 300);
    el.style.transform = `translateX(${p * 120}px)`;
    if (p < 1) slide(start);
  });
}

after.code:
const anim = el.animate(
  [{ transform: 'translateX(0)' }, { transform: 'translateX(120px)' }],
  { duration: 300, easing: 'ease-out' }
);
await anim.finished;
